// Aggregate rows from strictly read-only Chatwoot DB. Never output PII or permit sends.
// Operator verified account 2 / display campaign 2; no AGE attempt mapping established.
const rows=$input.all().map(x=>x.json||{}).filter(x=>Object.keys(x).length);
const now=new Date().toISOString();
const base={mode:'READ_ONLY',source:'CHATWOOT_POSTGRES_CAMPAIGN_RECIPIENT_SNAPSHOT',
  checkedAt:now,chatwootAccountId:2,sends:0,crmEventWrites:0,
  dataTableWrites:0,espocrmMappingVerified:false,providerIdOriginIndependentlyVerified:false,
  licensePermissionVerified:false,completeHistoricalEventLog:false};
if(rows.some(x=>x.error||x.message?.includes?.('permission denied'))) {
  return [{json:{...base,status:'BLOCKED',reason:'POSTGRES_QUERY_FAILED_OR_ACCESS_DENIED',
    note:'Check SELECT-only credentials, campaigns/campaign_recipients/inboxes grants, version and entitlement. Raw DB errors withheld.'}}];
}
if(!rows.length) {
  return [{json:{...base,status:'NO_MATCHING_CAMPAIGNS',reportCount:0,reports:[],
    note:'No one-off WhatsApp campaigns returned for this account; not proof of zero sends.'}}];
}
const failures=[];
const count=(v,label)=>{const n=Number(v);if(!Number.isSafeInteger(n)||n<0)throw Error('INVALID_COUNT_'+label);return n;};
const asErrors=(v)=>{let o=v;if(typeof v==='string'){try{o=JSON.parse(v);}catch{o=null;}}
  if(!o||typeof o!=='object'||Array.isArray(o))throw Error('INVALID_ERROR_COUNTS');
  const out={};for(const [k,vv] of Object.entries(o)){out[k]=count(vv,'ERROR');}
  return out;};
const reports=rows.map(r=>{
  const reasons=[];
  const state={queued:count(r.queued,'QUEUED'),skipped:count(r.skipped,'SKIPPED'),
    sentOnly:count(r.sent_only,'SENT'),deliveredOnly:count(r.delivered_only,'DELIVERED'),
    readConfirmed:count(r.read_confirmed,'READ'),failed:count(r.failed,'FAILED')};
  const audience=count(r.audience,'AUDIENCE');
  const delivered=state.deliveredOnly+state.readConfirmed;
  if(Object.values(state).reduce((sum,n)=>sum+n,0)!==audience)reasons.push('STATUS_TOTAL_MISMATCH');
  if(r.delivered_including_read!==undefined&&count(r.delivered_including_read,'DELIVERED_TOTAL')!==delivered)
    reasons.push('DELIVERED_READ_UNION_MISMATCH');
  const ids=count(r.provider_id_present,'PROVIDER_ID'),wamid=count(r.wamid_format,'WAMID');
  const timestamps={delivered:count(r.delivered_timestamps,'DELIVERED_TS'),
    read:count(r.read_timestamps,'READ_TS'),failed:count(r.failure_timestamps,'FAILED_TS')};
  const coded=count(r.coded_failures,'CODED_FAIL');
  const errorCodeCounts=asErrors(r.error_code_counts);
  if(Object.values(errorCodeCounts).reduce((a,b)=>a+b,0)!==state.failed)reasons.push('ERROR_ROLLUP_MISMATCH');
  if(ids>audience||wamid>ids||coded>state.failed)reasons.push('EVIDENCE_COUNT_EXCEEDS_AUDIENCE');
  if(ids<audience)reasons.push('PROVIDER_IDS_INCOMPLETE');
  if(wamid<ids)reasons.push('NON_WAMID_ID_FORMAT');
  if(timestamps.read<state.readConfirmed)reasons.push('READ_TIMESTAMPS_INCOMPLETE');
  if(timestamps.delivered<delivered)reasons.push('DELIVERY_TIMESTAMPS_INCOMPLETE');
  if(timestamps.failed<state.failed)reasons.push('FAILURE_TIMESTAMPS_INCOMPLETE');
  if(coded<state.failed)reasons.push('MISSING_META_ERROR_CODES');
  if(audience===0)reasons.push('NO_RECIPIENT_EVIDENCE');
  const serious=reasons.some(x=>['STATUS_TOTAL_MISMATCH','DELIVERED_READ_UNION_MISMATCH',
    'ERROR_ROLLUP_MISMATCH','EVIDENCE_COUNT_EXCEEDS_AUDIENCE'].includes(x));
  const report={accountId:r.account_id,chatwootCampaignInternalId:r.internal_campaign_id,
    chatwootCampaignDisplayId:r.campaign_display_id,campaignName:r.campaign_name,
    chatwootInboxId:r.inbox_id,counts:{audience,...state,deliveredIncludingRead:delivered,
      providerAcceptedBySourceId:ids,wamidFormatCount:wamid,codedFailures:coded},
    recordedTimestamps:timestamps,errorCodeCounts,lastRecipientUpdate:r.last_recipient_update||null,
    readPctOfDelivered:delivered?Number((state.readConfirmed/delivered*100).toFixed(2)):null,
    mapping:'UNMATCHED',canWriteEspoEvents:false,status:serious?'BLOCKED':reasons.length?'PARTIAL':'SNAPSHOT_VALID',
    reasons};
  if(serious)failures.push('CAMPAIGN_VALIDATION_FAILED');
  return report;
});
const limited=rows.length>=201;
return [{json:{...base,status:failures.length?'BLOCKED':limited||reports.some(r=>r.status!=='SNAPSHOT_VALID')?'PARTIAL':'SNAPSHOT_VALID',
  reason:failures.length?'DATA_INCONSISTENT':limited?'SCAN_LIMIT_201_REACHED':null,
  reportCount:reports.length,scanLimit:201,scanComplete:!limited,reports,
  note:'Current Chatwoot recipient snapshots only; not Meta event history or mapped EspoCRM attempts. Read is included once in Delivered.'}}];
